// Each card remembers its own IN/OUT state independently.
// First click always produces IN (initial state is treated as having last been OUT).
var cardUid = msg.payload.cardUid;
var lastState = flow.get(cardUid) || 'OUT';
var nextState = (lastState === 'OUT') ? 'IN' : 'OUT';
flow.set(cardUid, nextState);

msg.payload = { cardUid: cardUid, direction: nextState };
msg.headers = {
  'Content-Type': 'application/json',
  'Authorization': 'Bearer ' + env.get('VELTRO_JWT')
};

return msg;

if (msg.statusCode === 201 && msg.payload && msg.payload.data) {
  var entry = msg.payload.data;
  var icon = (entry.direction === 'IN') ? '🟢 IN' : '🔴 OUT';
  msg.payload = icon + ' | ' + (entry.memberName || 'Unknown') + ' | ' + entry.cardUid + ' @ ' + entry.timestamp;
} else if (msg.statusCode === 422) {
  msg.payload = '❌ Rejected: ' + (msg.payload.message || 'Card inactive or member suspended');
} else if (msg.statusCode === 503) {
  msg.payload = '⚠️ Service unavailable: ' + (msg.payload.message || 'Card validation failed — is user-service running?');
} else if (msg.statusCode === 429) {
  msg.payload = '⚠️ Rate limited: too many requests';
} else {
  msg.payload = '⚠️ HTTP ' + msg.statusCode + ': ' + JSON.stringify(msg.payload);
}
return msg;

var rand = function(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; };
var randFloat = function(min, max) { return Math.round((Math.random() * (max - min) + min) * 10) / 10; };

msg.payload.durationMinutes = rand(20, 90);
msg.payload.caloriesBurned  = rand(200, 800);
msg.payload.avgHeartRate    = rand(110, 175);
msg.payload.distanceKm     = randFloat(1.0, 15.0);

msg.headers = {
  'Content-Type': 'application/json',
  'Authorization': 'Bearer ' + env.get('VELTRO_JWT')
};

node.warn('Session for memberId=' + msg.payload.memberId + ' (' + msg.payload.memberEmail + '): ' + JSON.stringify({
  machine: msg.payload.machineType,
  duration: msg.payload.durationMinutes,
  calories: msg.payload.caloriesBurned
}));

return msg;

if (msg.statusCode === 201 && msg.payload && msg.payload.data) {
  var s = msg.payload.data;
  msg.payload = '✅ Session saved: memberId=' + s.memberId + ' | ' + s.machineType + ' | ' + s.durationMinutes + 'min | ' + s.caloriesBurned + ' kcal | ' + s.distanceKm + 'km';
} else if (msg.statusCode === 429) {
  msg.payload = '⚠️ Rate limited';
} else {
  msg.payload = '❌ Error ' + msg.statusCode + ': ' + JSON.stringify(msg.payload);
}
return msg;
